customMethods.script:
system.perspective.print("deleteAttributes() called for %s"%self.view.custom.table.selection.data)

for row in self.view.custom.table.selection.data:
	retVal, msg = system.kanoa.attribute.deleteAttribute(row['attributeId'], self.view.custom.security.userId)

	if retVal: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Attribute has bene deleted'})
	else: system.perspective.sendMessage('showFailerToast', {'message': msg})

self.view.refreshBinding("custom.filter.data")	 #Update the Tree Selector
self.view.refreshBinding("custom.table.data")

return

